const STATIC_BINARY = {"/assets/whaleprint-token-512.png":"","/assets/whaleprint-social-banner.png":"","/assets/whaleprint-x-banner.png":"","/assets/whaleprint-favicon-64.png":""};

const CONTENT_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml; charset=utf-8',
  '.png': 'image/png',
  '.txt': 'text/plain; charset=utf-8'
};
const COMMON_HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'X-Frame-Options': 'DENY',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()'
};
function staticRoute(path, method) {
  let normalized = path === '/' ? '/index.html' : path;
  if (!Object.prototype.hasOwnProperty.call(STATIC_TEXT, normalized) &&
      !Object.prototype.hasOwnProperty.call(STATIC_BINARY, normalized)) return null;
  const match = /\.[a-z0-9]+$/i.exec(normalized);
  const type = CONTENT_TYPES[match?.[0] ?? ''] || 'application/octet-stream';
  const headers = {
    ...COMMON_HEADERS,
    'Content-Type': type,
    'Cache-Control': normalized === '/index.html' ? 'public, max-age=120' : 'public, max-age=3600'
  };
  if (method === 'HEAD') return new Response(null, { status: 200, headers });
  if (Object.prototype.hasOwnProperty.call(STATIC_TEXT, normalized)) {
    return new Response(STATIC_TEXT[normalized], { status: 200, headers });
  }
  const encoded = STATIC_BINARY[normalized];
  const bytes = Uint8Array.from(atob(encoded), c => c.charCodeAt(0));
  return new Response(bytes, { status: 200, headers });
}

/* Solana scanner logic */
/**
 * WhalePrint read-only Solana liquidity/market conditions scanner.
 * Cloudflare Worker at GET /api/scan?mint=<Solana mint address>
 * Data: DEX Screener token-pairs/v1. No wallet credentials or private keys.
 */

const SOLANA_MINT_RE = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/;

function numeric(value) {
  if (value === null || value === undefined || value === '') return null;
  const num = Number(value);
  return Number.isFinite(num) && num >= 0 ? num : null;
}
function signedNumeric(value) {
  if (value === null || value === undefined || value === '') return null;
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
}
function safeString(value, max = 120) {
  return typeof value === 'string' ? value.slice(0, max) : '';
}
function safeUrl(value) {
  if (typeof value !== 'string') return null;
  try {
    const url = new URL(value);
    return ['https:', 'http:'].includes(url.protocol) ? url.toString() : null;
  } catch {
    return null;
  }
}

function makeSignals(pair, fetchedAtMs) {
  const signals = [];
  const add = (type, title, detail) => signals.push({ type, title, detail });
  const usd = numeric(pair.liquidity?.usd);
  const age = numeric(pair.pairCreatedAt) === null ? null : (fetchedAtMs - Number(pair.pairCreatedAt)) / 3600000;
  const change = signedNumeric(pair.priceChange?.h24);
  const volume = numeric(pair.volume?.h24);
  const buys = numeric(pair.txns?.h24?.buys);
  const sells = numeric(pair.txns?.h24?.sells);

  if (usd === null) add('unknown', 'Liquidity data unavailable', 'DEX Screener did not report USD liquidity for this pool.');
  else if (usd < 10000) add('caution', 'Very thin liquidity', 'Under $10K reported USD liquidity in the most liquid observed pool.');
  else if (usd < 50000) add('watch', 'Limited liquidity', 'Under $50K reported USD liquidity; price impact may be significant.');
  else add('observed', 'Liquidity reported', 'At least $50K in reported USD liquidity in the selected pool. This does not establish a lock.');

  if (age === null || age < 0) add('unknown', 'Pool age unavailable', 'The provider did not return a valid pool creation time.');
  else if (age < 24) add('watch', 'Very new trading pool', 'The selected pool is under 24 hours old; there is limited trading history.');
  else if (age < 24 * 7) add('watch', 'Young trading pool', 'The selected pool is under seven days old.');
  else add('observed', 'Established pool history', 'The selected pool was created at least seven days ago; longevity does not establish safety.');

  if (change !== null && change <= -50) add('caution', 'Sharp 24h price decline', 'The selected pool reports a decline of 50% or more over 24 hours.');
  else if (change !== null && Math.abs(change) >= 60) add('watch', 'Large 24h price movement', 'The selected pool reports a 24h price move of at least 60%.');

  if (buys !== null && sells !== null && buys + sells >= 30) {
    const oneSided = Math.max(buys, sells) / (buys + sells);
    if (oneSided > 0.85) add('watch', 'One-sided transaction count', 'More than 85% of observed 24h swaps are one direction. Counts are not wallet-unique or dollar-weighted.');
  }
  if (volume !== null && usd !== null && usd > 0 && volume / usd > 25) {
    add('watch', 'High volume relative to pool size', '24h reported volume exceeds 25× the pool liquidity. This is not proof of wash trading.');
  }
  if (!Array.isArray(pair.info?.websites) || pair.info.websites.length === 0) {
    add('unknown', 'Website not listed', 'No project website is included in this pair’s market-data metadata.');
  }
  return signals;
}

function normalizePairs(rawPairs, mint, nowMs = Date.now()) {
  const pairs = rawPairs
    .filter((p) => p && p.chainId === 'solana' && (p.baseToken?.address === mint || p.quoteToken?.address === mint))
    .sort((a, b) => (numeric(b.liquidity?.usd) || 0) - (numeric(a.liquidity?.usd) || 0));
  if (!pairs.length) return null;
  const p = pairs[0];
  const target = p.baseToken?.address === mint ? p.baseToken : p.quoteToken;
  const prices = {
    usd: signedNumeric(p.priceUsd),
    change5m: signedNumeric(p.priceChange?.m5),
    change1h: signedNumeric(p.priceChange?.h1),
    change6h: signedNumeric(p.priceChange?.h6),
    change24h: signedNumeric(p.priceChange?.h24)
  };
  const ageMs = numeric(p.pairCreatedAt) !== null && Number(p.pairCreatedAt) <= nowMs ? nowMs - Number(p.pairCreatedAt) : null;
  const otherPools = pairs.slice(0, 6).map((pool) => ({
    dex: safeString(pool.dexId, 40),
    pairAddress: safeString(pool.pairAddress, 90),
    liquidityUsd: numeric(pool.liquidity?.usd),
    url: typeof pool.url === 'string' && /^https:\/\/dexscreener\.com\//i.test(pool.url) ? pool.url : null
  }));
  return {
    name: safeString(target?.name, 80) || 'Unknown token',
    symbol: safeString(target?.symbol, 24) || '—',
    mint,
    chain: 'solana',
    fetchedAt: new Date(nowMs).toISOString(),
    source: 'DEX Screener',
    pair: {
      dex: safeString(p.dexId, 40),
      address: safeString(p.pairAddress, 90),
      url: typeof p.url === 'string' && /^https:\/\/dexscreener\.com\//i.test(p.url) ? p.url : null,
      createdAt: ageMs === null ? null : new Date(Number(p.pairCreatedAt)).toISOString(),
      ageHours: ageMs === null ? null : Math.round(ageMs / 360000) / 10
    },
    prices,
    liquidityUsd: numeric(p.liquidity?.usd),
    marketCapUsd: numeric(p.marketCap),
    fdvUsd: numeric(p.fdv),
    volume24hUsd: numeric(p.volume?.h24),
    txns24h: { buys: numeric(p.txns?.h24?.buys), sells: numeric(p.txns?.h24?.sells) },
    poolsObserved: pairs.length,
    otherPools,
    socials: (Array.isArray(p.info?.socials) ? p.info.socials : [])
      .map((x) => ({ platform: safeString(x.platform, 40), url: safeUrl(x.url) })).filter((x) => x.url).slice(0, 4),
    websites: (Array.isArray(p.info?.websites) ? p.info.websites : [])
      .map((x) => safeUrl(x.url)).filter(Boolean).slice(0, 3),
    signals: makeSignals(p, nowMs),
    coverage: { holderConcentration: false, mintAuthority: false, lpLock: false, creatorIdentity: false },
    note: 'Descriptive market conditions only. This report does not verify token security or predict performance.'
  };
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      'Cache-Control': status === 200 ? 'public, max-age=15' : 'no-store',
      'X-Content-Type-Options': 'nosniff',
      'Access-Control-Allow-Origin': '*'
    }
  });
}

async function onRequestGet({ request }) {
  const url = new URL(request.url);
  const mint = (url.searchParams.get('mint') || '').trim();
  if (!SOLANA_MINT_RE.test(mint)) {
    return json({ error: 'Enter a Solana token mint address (32–44 Base58 characters).' }, 400);
  }
  try {
    const sourceUrl = `https://api.dexscreener.com/token-pairs/v1/solana/${encodeURIComponent(mint)}`;
    const response = await fetch(sourceUrl, {
      headers: { Accept: 'application/json', 'User-Agent': 'WhalePrint/1.0 (+read-only-token-research)' },
      signal: AbortSignal.timeout(9000)
    });
    if (response.status === 429) return json({ error: 'Market data provider is rate-limiting requests. Try again shortly.' }, 503);
    if (!response.ok) return json({ error: 'Market data provider is temporarily unavailable.' }, 502);
    const raw = await response.json();
    if (!Array.isArray(raw)) return json({ error: 'Unexpected market-data response.' }, 502);
    const result = normalizePairs(raw, mint);
    if (!result) return json({ error: 'No Solana DEX pools found for this mint. It might be new, inactive, or not indexed.' }, 404);
    return json(result);
  } catch {
    return json({ error: 'Could not reach the market data provider. Try again shortly.' }, 502);
  }
}


/* Single-file Worker router */
export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname;
    if (path === '/api/health') {
      if (request.method !== 'GET') return json({ error: 'Method not allowed' }, 405);
      return json({ ok: true, service: 'WhalePrint', mode: 'single-file-worker', api: '/api/scan' });
    }
    if (path === '/api/scan') {
      if (request.method !== 'GET') return json({ error: 'Method not allowed' }, 405);
      return onRequestGet({ request });
    }
    if (path.startsWith('/api/')) return json({ error: 'Unknown API route' }, 404);
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return new Response('Method not allowed', { status: 405, headers: COMMON_HEADERS });
    }
    return staticRoute(path, request.method) ?? new Response('Page not found', { status: 404, headers: COMMON_HEADERS });
  }
};
